        if inb(nx, ny) and (nx, ny) not in obs_cells:
            legal.append((dx, dy))
    if not legal:
        return [0, 0]

    def dist(ax, ay, bx, by):
        ax, ay, bx, by = int(ax), int(ay), int(bx), int(by)
        return max(abs(ax - bx), abs(ay - by))

    if not resources:
        # No known resources: head to center-ish deterministically while keeping away from walls
        tx, ty = w // 2, h // 2
        best = None
        bestv = None
        for dx, dy in legal:
            nx, ny = sx + dx, sy + dy
            v = dist(nx, ny, tx, ty)
            if bestv is None or v < bestv:
                bestv = v
                best = (dx, dy)
        return [best[0], best[1]] if best is not None else [0, 0]

    # Choose target resource by net advantage (prefer resources we can reach sooner)
    best_target = None
    best_score = None
    opp_threat = -1e9
    for rx, ry in resources:
        myd = dist(sx, sy, rx, ry)
        opd = dist(ox, oy, rx, ry)
        # net advantage: lower myd better, higher opd better; tie-break by coordinates
        score = (opd - myd, -rx, -ry)
        # Use lexicographic on tuple; Python compares elementwise
        if best_score is None or score > best_score:
            best_score = score
            best_target = (rx, ry)
        elif score == best_score:
            # deterministic tie already via -rx,-ry, but keep stable
            pass

    rx, ry = best_target
    # If opponent can reach significantly sooner, pick the resource where opponent is not favored
    if best_score is not None and isinstance(best_score[0], (int, float)) and best_score[0] < 0:
        # Search for any resource where we are at least as fast as opponent
        candidates = []
        for tx, ty in resources:
            myd = dist(sx, sy, tx, ty)
            opd = dist(ox, oy, tx, ty)
            if myd <= opd:
                candidates.append((myd, tx, ty))
        if candidates:
            candidates.sort()
            _, rx, ry = candidates[0]

    # Choose move that reduces our distance to target and avoids allowing opponent to get closer
    best_move = None
    best_val = None
    for dx, dy in legal:
        nx, ny = sx + dx, sy + dy
        myd = dist(nx, ny, rx, ry)
        opd = dist(ox, oy, rx, ry)

        # Opponent-denial proxy: prefer moves that increase opponent's distance to our next cell
        deny = dist(ox, oy, nx, ny)

        # Also mildly prefer moves that keep us from drifting away from target
        val = (myd, -deny, dx, dy)
        if best_val is None or val < best_val:
            best_val = val
            best_move = (dx, dy)

    if best_move is None:
        return [0, 0]


